<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const values=ref<components['schemas']['MemoryItem'][]>([]);const selected=ref<components['schemas']['MemoryItem']>();const error=ref('');const message=ref('');const conversation=crypto.randomUUID();const proposals=ref<components['schemas']['MemoryProposal'][]>([]);const accepted=ref<Record<string,boolean>>({});function select(item:components['schemas']['MemoryItem']){selected.value=window.structuredClone(item)}async function refresh(){values.value=requireData(await client.GET('/api/admin/memory'))}onMounted(async()=>{try{await refresh()}catch(cause){error.value=errorMessage(cause)}});async function save(){if(!selected.value)return;try{requireData(await client.PUT('/api/admin/memory',{body:selected.value}));await refresh()}catch(cause){error.value=errorMessage(cause)}}async function ask(){try{proposals.value=requireData(await client.POST('/api/admin/memory/assistant',{body:{conversation,message:message.value}}));accepted.value=Object.fromEntries(proposals.value.map(value=>[value.id,value.change!=='unchanged']))}catch(cause){error.value=errorMessage(cause)}}async function apply(){try{requireData(await client.POST('/api/admin/memory/assistant/{conversation}/apply',{params:{path:{conversation}},body:{accepted:accepted.value}}));proposals.value=[];await refresh()}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="长期记忆" description="各 AI 任务按映射取用条目；单条和总注入量均有限制。"/><p v-if="error" class="text-danger">{{ error }}</p><div class="grid gap-6 lg:grid-cols-[16rem_1fr]"><nav class="grid content-start gap-2"><button v-for="item in values" :key="item.id" class="rounded-card border border-border p-3 text-start" @click="select(item)">{{ item.title }}<small class="block text-muted">{{ item.content.length }} 字节</small></button></nav><form v-if="selected" class="grid gap-4" @submit.prevent="save"><label>标题<input v-model="selected.title" class="nw-input" :disabled="selected.readOnly"></label><label>说明<input v-model="selected.description" class="nw-input" :disabled="selected.readOnly"></label><label>内容<textarea v-model="selected.content" rows="16" class="nw-input" :disabled="selected.readOnly" /></label><button class="nw-button" :disabled="selected.readOnly">保存</button></form></div><section class="mt-10 border-t border-border pt-6"><h2 class="text-xl font-semibold">记忆助手</h2><textarea v-model="message" rows="4" class="nw-input mt-3" placeholder="说明希望记住、修改或删除的内容"/><button class="nw-button mt-3" @click="ask">生成修改提议</button><label v-for="proposal in proposals" :key="proposal.id" class="mt-3 flex gap-3 rounded-card border border-border p-3"><input v-model="accepted[proposal.id]" type="checkbox"><span><strong>{{ proposal.change }} · {{ proposal.id }}</strong><small class="block text-muted">{{ proposal.reason }}</small></span></label><button v-if="proposals.length" class="nw-button mt-4" @click="apply">应用选中的提议</button></section></template>
